-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (Revalida 2024/2, revalida-2024-2): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 26 correções de texto em 18 questões (20 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'revalida-2024-2';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2024_2_q012","code":"REV-2024.2-Q012","campos":{"statement":{"antes_md5":"e6c8f3916dd7bc9bb01772b56746cd3a","depois":"Uma mulher de 45 anos, hipertensa controlada, com índice de massa corporal de 20 kg/m², é submetida a procedimento de correção de hérnia umbilical em regime ambulatorial sob anestesia local. O anel herniário aparenta ter cerca de 1,5 cm de diâmetro. Diante disso, o médico opta pela correção sem o uso de telas de reforço. Em relação ao uso profilático de antibióticos nesse caso, é correto afirmar que a"}}},{"id":"revalida_2024_2_q016","code":"REV-2024.2-Q016","campos":{"statement":{"antes_md5":"b01adfd02cf478bbd3f01d02094ace1e","depois":"Um homem de 28 anos é trazido ao hospital pelo SAMU 40 minutos após ter sofrido atropelamento. Ele foi encontrado desacordado no local do acidente, apresentando Glasgow 6. Ao chegar à unidade de saúde, apresentava Glasgow 3, pressão arterial de 150 × 100 mmHg, irregularidade respiratória e frequência cardíaca de 50 batimentos por minuto, sendo realizada a intubação orotraqueal. Ao exame físico, apresenta-se em mau estado geral, paciente em uso de ventilação mecânica com ausência de ruídos adventícios à ausculta respiratória. O paciente está comatoso, com Glasgow 3 e com pupilas isocóricas e midriáticas, constata-se, ainda, reflexos fotomotores direto e consensual ausentes; reflexo córneo-palpebral ausente e reflexo óculo-cefálico ausente. Paciente sem sedação. Foi levantada a hipótese diagnóstica de hipertensão intracraniana pela equipe médica. Diante dessas informações, o achado clínico que confirma essa hipótese é a presença de"}}},{"id":"revalida_2024_2_q023","code":"REV-2024.2-Q023","campos":{"statement":{"antes_md5":"3cb37958eb74c8bd65d7a14b76044bbe","depois":"Um recém-nascido (RN) a termo, afrodescendente, do sexo masculino, com 26 dias, apresenta quadro de icterícia neonatal zona III de Kramer desde o 3.º dia de vida. Seus pais negam outras queixas e afirmam que ambos são consanguíneos (primos). Encontra-se em uso de fórmula láctea com ganho ponderal adequado. Não houve intercorrências na gestação e parto. Diante dessas informações, o médico solicita outros exames. A criança, então, retorna à consulta ambulatorial com propedêutica complementar solicitada há 7 dias. Os resultados dos exames realizados podem ser verificados a seguir. A tipagem sanguínea da mãe é O+ e do recém-nascido é A-. O Coombs direto (ou teste de antiglobulina direto) apresenta resultado negativo. Exame laboratorial Resultado Valor de referência Hemoglobina 12 g/dL 12,5 a 20,5 g/dL Hematócrito 36% 39 a 63% VCM 80 fL 86 a 124 fL HCM 26 pg 28 a 40 pg CHCM 25 g/dL 28 a 38 g/dL Plaquetas 450.000/mm³ 250.000 a 500.000/mm³ Reticulócitos 6,4 % 2,0 a 6,0% Bilirrubinas totais 12,8 mg/dL RN 3 - 5 dias: 10,30 mg/dL Bilirrubinas diretas 0,8 mg/dL RN 3 - 5 dias: até 0,4 mg/dL Bilirrubinas indiretas 12,0 g/dL TSH 5 μU/mL < 10 μU/mL Considerando-se o caso clínico e os exames complementares realizados, qual é a hipótese diagnóstica mais provável?","sem_tabela_md5":"117b7e92239663862bd3101f52da9d7f"}}},{"id":"revalida_2024_2_q027","code":"REV-2024.2-Q027","campos":{"statement":{"antes_md5":"030f3856c3299ddae4f71ec824837de7","depois":"Um paciente de 65 anos vai ao SAMU referindo dor lombar aguda irradiada para membro inferior direito, após queda da própria altura ocorrida há 6 horas. Ele está utilizando anti-inflamatório e analgésico via oral e apresenta retenção urinária e dor em hipogástrio. Possui histórico de dor lombar crônica e osteoartrite em coluna lombar e coxofemoral direita. Ao exame físico, apresenta dor à palpação de região púbica com massa palpável na região suprapúbica; força muscular preservada em membros inferiores e reflexos patelar e aquileu preservados bilateralmente; hipoestesia tátil em face posterior de coxa e perna direita e anestesia em região perineal bilateral. Ressonância magnética de coluna lombar mostrou alterações degenerativas de discos intervertebrais L3-L4 / L4-L5 / L5-S1, com redução de forames intervertebrais correspondentes, osteófitos posteriores em corpos vertebrais de L4, L5 e S1, além de protrusão discal volumosa centro-foraminal à direita em L4-L5, causando estenose foraminal nesse nível. Diante dessas informações, a conduta terapêutica adequada, no caso desse paciente, é realizar"},"D":{"antes_md5":"89803205e978b498f660e1560328787f","depois":"tratamento conservador e manter uso de anti-inflamatório."}}},{"id":"revalida_2024_2_q033","code":"REV-2024.2-Q033","campos":{"statement":{"antes_md5":"d89d02a181cb7bd05f5df7a4b37a7dca","depois":"Um menino de 10 anos, escolar, é levado à unidade de pronto-atendimento com queixa de dor em bolsa escrotal esquerda iniciada há 3 horas. A criança é eutrófica, sem antecedendes mórbidos e sem história de trauma ou de quedas. Ao exame testicular, o local da dor apresenta-se com edema e o testículo esquerdo encontra-se localizado em porção superior ao contralateral, próximo ao anel inguinal externo, com reflexo cremastérico abolido, cuja manobra de elevação é dolorosa. Nesse caso, a conduta médica correta é realizar"}}},{"id":"revalida_2024_2_q037","code":"REV-2024.2-Q037","campos":{"statement":{"antes_md5":"ecae004d96f0083c8fb04ea656e61d94","depois":"Uma paciente de 64 anos é socorrida, em via pública, pelo SAMU por queda da própria altura com rebaixamento do nível de consciência. Ao exame físico, constata-se ferida corto-contusa na região occipital direita de 3 cm; Glasgow 9; pressão arterial de 110 × 70 mmHg; e frequência cardíaca de 88 batimentos por minuto. Ao exame pulmonar, percebe-se expansibilidade preservada bilateralmente e, à ausculta cardíaca, constata-se bulhas rítmicas e normofonéticas. O abdome apresenta-se flácido e indolor. Nesse caso, a conduta imediata deve ser a"}}},{"id":"revalida_2024_2_q041","code":"REV-2024.2-Q041","campos":{"statement":{"antes_md5":"9e4af18c26dc6100b935def2a962cc10","depois":"Uma mulher de 33 anos vai a uma consulta com um clínico geral por se sentir muito deprimida, referindo tristeza e desânimo, que começaram há 6 meses. Ela conta que é natural e procedente de São Paulo, programadora de computadores, católica não praticante, casada há 6 anos, com dois filhos, e que é sedentária. Refere sentir muita fadiga, cansaço, indisposição e sono e que ganhou 7 kg nesse período. Nega ter pensamentos de morte, de culpa ou de menos-valia. Conta, também, que recebeu diagnóstico de depressão e, por isso, usou fluoxetina durante 2 meses, até 60 mg por dia, sem apresentar melhora significativa. Por fim, referiu ter irregularidade menstrual e constipação. Ao exame, apresenta-se hidratada, corada, afebril, sem edemas, anictérica. Seus sinais vitais estão sem alterações, exceto a frequência cardíaca que está 48 batimentos por minuto em repouso. À ausculta cardíaca, notam-se bulhas normofonéticas, sem sopros. Diante desse quadro, o principal diagnóstico diferencial a ser investigado é"}}},{"id":"revalida_2024_2_q042","code":"REV-2024.2-Q042","campos":{"statement":{"antes_md5":"c5deb64d8e8deb0fa78525ebeb1754bb","depois":"Um paciente, que está no 5º dia pós-operatório de gastroduodenopancreatectomia para o tratamento de neoplasia da papila duodenal, é encaminhado a consulta. Ao examiná-lo, o médico nota o paciente normocárdico, afebril, com drenagem de 500 mL/24h de secreção clara e límpida por meio de dreno abdominal. A ferida cirúrgica está sem sinais de flogose. Nesse caso, para o diagnóstico de eventual complicação, deve-se realizar"}}},{"id":"revalida_2024_2_q044","code":"REV-2024.2-Q044","campos":{"statement":{"antes_md5":"531c69c0c6c1cacb8d6ba6cd2250c493","depois":"Uma primigesta, com idade gestacional de 39 semanas, assistida em pré-natal de baixo risco, é admitida no pronto-socorro obstétrico com queixa de “cólica forte que vai e volta”, nega outras queixas. Com intuito de avaliar se a paciente está em trabalho de parto, o médico pede consentimento à gestante para executar o exame físico, informando que precisa realizar, entre outras etapas, a avaliação da dinâmica uterina. Sobre a avaliação da dinâmica uterina, o médico explica para a gestante que o procedimento consiste em colocar a mão espalmada"}}},{"id":"revalida_2024_2_q053","code":"REV-2024.2-Q053","campos":{"statement":{"antes_md5":"305e3fbb73a3fec73be9369106863119","depois":"Um recém-nascido (RN) com 25 dias de vida, masculino, é levado por sua mãe para consulta na unidade de saúde com história de febre de 39 °C, recusa alimentar e vômitos. A mãe relata que seu filho está em aleitamento materno exclusivo e que é a primeira vez que ele fica doente. Ao exame físico, nota-se RN irritado, com temperatura axilar de 38,3 °C, sem nenhuma outra alteração. Ao hemograma, observa-se leucocitose com neutrofilia e plaquetas normais. À rotina de urina, nota-se piúria, estearase positiva, nitrito positivo e flora aumentada. Em Gram de gota de urina não centrifugada, é constatada presença de bastonete Gram negativo (> 1 bactéria/campo de imersão). Considerando o provável diagnóstico, a conduta imediata do médico deve ser"}}},{"id":"revalida_2024_2_q057","code":"REV-2024.2-Q057","campos":{"statement":{"antes_md5":"0514b637c9d1f92dc53e7cc8aee5b20f","depois":"Uma mulher de 29 anos procura atendimento na emergência com quadro agudo de dor abdominal em fossa ilíaca esquerda, com irradiação para mesogástrio. Apresenta diarreia e náusea, nega ter tido febre. A paciente refere episódios de urgência fecal, com presença de muco e de sangue, e refere ter perdido 10% do peso corporal nos últimos 12 meses. Ela é tabagista ativa, nega etilismo e apresenta índice de massa corporal de 22 kg/m². Ao exame físico, apresenta dor abdominal à palpação em todo abdome inferior, sem defesa muscular ou descompressão brusca positiva. Com base nessas informações, é correto afirmar que o diagnóstico mais provável para o caso clínico apresentado é"}}},{"id":"revalida_2024_2_q066","code":"REV-2024.2-Q066","campos":{"statement":{"antes_md5":"a6970eae02eb5266779c4f0eef943737","depois":"Um homem de 67 anos comparece à consulta de rotina. Diagnosticado com diabetes mellitus tipo 2 há cerca de 12 meses, em uso regular de metformina 500 mg de 12 em 12 horas. Possui história prévia de infarto agudo do miocárdio há 5 anos. Comparece à consulta de acompanhamento com exames laboratoriais de controle recentes, que apresentam resultados semelhantes aos exames anteriores, realizados há 3 e há 6 meses. Exame Resultado Valor de Referência Ureia 28 mg/dL 13 a 43 mg/dL Creatinina 1,04 mg/dL 0,60 a 1,30 mg/dL taxa de filtração glomerular (TFG – CKP - EPI) 74,99 mL/min/1,73 m² > 90 mL/min/1,73 m² Glicemia de jejum 144 mg/dL < 100 mg/dL Hemoglobina glicada 7,2% 4,5 a 5,6% Albuminúria em amostra isolada de urina 234 mg/L < 30 mg/L Observação: TFG – CKD - EPI corresponde à estimativa da taxa de filtração glomerular pela fórmula proposta pela ChronicKidneyDiseaseEpidemiologyCollaboration. A conduta recomendada para esse paciente é","sem_tabela_md5":"fecce356ca552c06bd467483039e8846"},"D":{"antes_md5":"fb2953dff1e97422f58a877ebeb7efd3","depois":"associar um medicamento inibidor do receptor SGLT2 (cotransportador sódio-glicose 2) e manter acompanhamento habitual."}}},{"id":"revalida_2024_2_q073","code":"REV-2024.2-Q073","campos":{"statement":{"antes_md5":"60b9abe849ebd7e8d1712ac3a1a4dbe3","depois":"Na maternidade, um recém-nascido (RN) de 30 horas de vida, evolui com icterícia zona 3 de Kramer. Nasceu com 36 semanas de idade gestacional (IG), de parto vaginal, tendo algumas equimoses durante o parto. A tipagem sanguínea da mãe é O- e do RN é B+. Os exames laboratoriais, realizados quando a criança estava com 32 horas de vida, revelam: Exame Valor bilirrubinas totais 13 mg/dL bilirrubinas diretas 1,5 mg/dL bilirrubinas indiretas 11,5 mg/dL Coombs direto positivo antígeno-D positivo hemoglobina 13,0 g/dL reticulócitos 2,0% O pediatra, ao ver esses resultados, iniciou fototerapia de alta intensidade e transferiu o paciente para unidade de cuidados neonatais. Após 4 horas de fototerapia (com 36 horas de vida) obteve-se: Exame Valor bilirrubinas totais 15 mg/dL bilirrubinas diretas 1,5 mg/dL bilirrubinas indiretas 13,5 mg/dL Tabela – Nível de bilirrubina total (mg/dL) para indicação de fototerapia e exsanguineotransfusão (EST) em RN IG ≥ 35 semanas. idade Bilirrubina total (mg/dL) Fototerapia Exsanguineotransfusão 35⁰⁄⁷ - 37⁶⁄⁷ semanas ≥38⁰⁄⁷ semanas 35⁰⁄⁷ - 37⁶⁄⁷ semanas ≥38⁰⁄⁷ semanas 24 horas 8 10 15 18 36 horas 9,5 11,5 16 20 48 horas 11 13 17 21 72 horas 13 15 18 22 96 horas 14 16 20 23 5 a 7 dias 15 17 21 24 Considerando-se o caso e a tabela de referência apresentados, a conduta médica adequada é","sem_tabela_md5":"9e6874590bd17f604deb470c36890c1c"}}},{"id":"revalida_2024_2_q076","code":"REV-2024.2-Q076","campos":{"statement":{"antes_md5":"260a4e10936c0c4db35df94ee9d729c6","depois":"Uma mulher de 24 anos procura atendimento hospitalar referindo quadro de cefaleia episódica, sudorese e taquicardia há 3 meses, com piora progressiva. Realizada a monitorização ambulatorial da pressão arterial (MAPA), identificou-se oscilação importante, caracterizando hipertensão paroxística. Definindo-se, como principal hipótese diagnóstica, a hipertensão arterial secundária, foram realizados os seguintes exames. Exame Amostra Resultado Valor de referência Ácido 5-hidroxiindolacético (5-HIAA) Urina 5 mg/24h 2 a 7 mg/24h Normetanefrina Urina > 2,2 nmol/L < 0,9 nmol/L Metanefrina Urina > 1,1 nmol/L < 0,5 nmol/L TSH Sangue 5 mUI/L 0,25 a 5 mUI/L T3 Sangue 132 ng/dL 60 a 182 ng/dL T4 livre Sangue 1,0 ng/dL 0,9 a 1,8 ng/dL Diante desses resultados, qual é a principal hipótese diagnóstica?","sem_tabela_md5":"9f9e8c4892f1805b25c40d3e11f6e6f4"}}},{"id":"revalida_2024_2_q078","code":"REV-2024.2-Q078","campos":{"statement":{"antes_md5":"5cf156c6cb77bd479908b7fcd3947d89","depois":"Durante avaliação em alojamento conjunto de uma maternidade de recém-nascido com 24 horas de vida, observa-se genitália de aparência masculina, mas com criptorquidia bilateral, sem palpação de testículos em canal inguinal. Diante da hipótese de um distúrbio de diferenciação sexual, e considerando-se questões éticas, legais e de risco-benefício, assinale a alternativa correta quanto à conduta adequada para esse caso."}}},{"id":"revalida_2024_2_q081","code":"REV-2024.2-Q081","campos":{"statement":{"antes_md5":"ccb1b2e4b71a082afdd0bdc2699aef87","depois":"Uma mulher de 31 anos é encaminhada à consulta ambulatorial por apresentar dores articulares intermitentes há 3 meses. Relata que as dores acometem as articulações das mãos, punhos, joelhos e tornozelos, de forma migratória e não aditiva. As dores pioram ao acordar e melhoram com a movimentação. Durante as crises, sente calor e apresenta rubor e edemas locais, sem deformidades articulares. Afirma estar mais cansada do que o habitual. Refere ter buscado atendimento médico na unidade de pronto-atendimento. Na ocasião, fez uso de analgésicos e anti-inflamatórios não esteroides, houve melhora momentânea, mas logo os sintomas reapareceram. Relata que, nas últimas consultas, sua pressão esteve elevada, sendo-lhe prescrito hidroclorotiazida 25 mg ao dia. Até o início desse quadro, não apresentava antecedentes pessoais, ou utilizava medicações de uso contínuo, apenas anticoncepcional hormonal oral. Refere que sua mãe tem diabete tipo 2. Nega etilismo e tabagismo, afirma ir à academia 3 a 4 vezes na semana. Na revisão de sistemas, refere ter dor e cianose nos dedos das mãos ao contato com água fria. Ao exame físico, apresenta dados vitais e antropométricos normais, mucosas descoradas (2+/4+) e ictéricas (1+/4+), úlceras orais indolores, com dor à palpação e movimentação das articulações das mãos, do punho e do joelho direito. Não apresenta edemas, calor, nódulos, crepitações ou deformidades. Demais segmentos estão sem anormalidades. Em hemograma, apresenta hemoglobina de 10,8%, leucócitos de 3.850 mm³, linfócitos em 1.300 mm³ e plaquetas em 88.000 mm³. Qual é o exame mais indicado para a conclusão diagnóstica?"}}},{"id":"revalida_2024_2_q092","code":"REV-2024.2-Q092","campos":{"statement":{"antes_md5":"a046ff81e1d7ea1164e9bebd75dd9395","depois":"Uma paciente de 24 anos, estudante, é atendida no pronto-socorro após sentir uma tumoração, de moderado volume, com hiperemia, em região retroauricular à direita e redução da acuidade auditiva. Relata apresentar, há 5 semanas, episódios repetidos de dor na orelha direita, que melhoravam com analgésico e calor local. Ao exame físico, nota-se presença de celulite retroauricular à direita, sem saída de secreção ou ponto de flutuação e sem secreção no conduto auditivo. Nesse caso, qual deve ser a conduta imediata para essa paciente?"}}},{"id":"revalida_2024_2_q098","code":"REV-2024.2-Q098","campos":{"statement":{"antes_md5":"a75e9ae0102c76dcc00de60d402a8b01","depois":"Um adolescente de 16 anos procura atendimento hospitalar com quadro de epigastralgia, náuseas e vômitos importantes há 4 dias, sendo internado para investigação. Ele foi submetido, há 2 meses, à cirurgia bariátrica tipo gastrectomia vertical, por obesidade mórbida, e apresentou, no pós-operatório, rápida perda de peso. O exame abdominal não apresenta alterações à inspeção, sinais de peritonite e de ascite ausentes. Considerando-se esses dados clínicos e os riscos de complicações e de doenças disabsortivas após esse tipo de cirurgia, assinale a alternativa que apresenta a hipótese diagnóstica mais provável e o exame complementar a ser solicitado."}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('revalida-2024-2', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('revalida-2024-2', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('revalida-2024-2', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'Revalida 2024/2: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 20)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'revalida-2024-2'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'revalida-2024-2' and situacao like 'pulado%'
) x order by ordem, resultado;
